package com._8x8.herd.device_logs.contract;

import java.util.Objects;
import java.util.Optional;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/**
 * An accepted upload file name, {@code <mac>-<suffix>}, or {@code <mac>-now-<suffix>} for a manual upload. {@code name}
 * is the name exactly as uploaded. Build one with {@link #parse}, so the fields always agree with the name.
 */
public record LogFileName(String name, MacAddress mac, FileType type, boolean manual) {

    private static final Pattern SHAPE = Pattern.compile("(.{12})-(now-)?(.+)");

    public LogFileName {
        Objects.requireNonNull(name, "name");
        Objects.requireNonNull(mac, "mac");
        Objects.requireNonNull(type, "type");
    }

    /**
     * Parses a name from {@code PUT /logs/<name>}. A name that is not accepted is empty.
     */
    public static Optional<LogFileName> parse(String name) {
        if (name == null) {
            return Optional.empty();
        }
        Matcher shape = SHAPE.matcher(name);
        if (!shape.matches()) {
            return Optional.empty();
        }
        boolean manual = shape.group(2) != null;
        Optional<MacAddress> mac = MacAddress.parse(shape.group(1));
        Optional<FileType> type = FileType.fromSuffix(shape.group(3)).filter(t -> !manual || t.manualAllowed());
        if (mac.isEmpty() || type.isEmpty()) {
            return Optional.empty();
        }
        return Optional.of(new LogFileName(name, mac.get(), type.get(), manual));
    }
}

